      "keystrokes": "du -sh /var/* /usr/* 2>/dev/null | sort -h | tail -15\n",
      "duration": 5
    },
    {
      "keystrokes": "dd if=/dev/zero of=/app/bigtest bs=1M count=150 2>&1 | tail -2; ls -la /app/bigtest; rm -f /app/bigtest\n",
      "duration": 3
    }
  ]
}

