    {
      "keystrokes": "python3 -c \"import tarfile, lzma; tarfile.open('/app/node.tar.xz','r:xz').extractall('/app'); print('extracted')\" && /app/node-v20.11.0-linux-x64/bin/node --version\n",
      "duration": 10
    }
  ]
}

{
  "analysis": "Waiting for the Python extraction command to complete and print node's version. The previous command may still be processing or has finished. I need to see the output to confirm node was extracted and works.",
  "plan": "Poll for the output of the extraction command. Once node --version prints, I'll retry yt-dlp with the node JS runtime to bypass the bot-detection.",
  "commands": [
    {
      "keystrokes": "",
      "duration": 3
    }
